def get_anagram(s):
    from collections import Counter
    n = len(s) // 2
    first = s[:n]
    second = s[n:]
    counts = Counter(second)
    for char in first:
        if counts[char] > 0:
            counts[char] -= 1
    return sum(counts.values())

if __name__ == '__main__':
    import sys
    s = sys.stdin.read().strip()
    if s:
        print(get_anagram(s))

