function getAnagram(s) {
    let n = Math.floor(s.length / 2);
    let first = s.slice(0, n);
    let second = s.slice(n);
    let counts = {};
    for (let char of second) counts[char] = (counts[char] || 0) + 1;
    for (let char of first) {
        if (counts[char] > 0) counts[char]--;
    }
    return Object.values(counts).reduce((a, b) => a + b, 0);
}

