def partition_array(k, numbers):
    from collections import Counter
    n = len(numbers)
    if n % k != 0:
        return "No"
    groups = n // k
    freq = Counter(numbers)
    for count in freq.values():
        if count > groups:
            return "No"
    return "Yes"

